INSERT INTO verses_yousafzai (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at, tags) VALUES
(17501, 'Isaiah 47:13', 'Isaiah', 47, 13, '&nbsp;تا له چې کومې مشورې درکړے کيږى نو د هغې نه تۀ ستړے يې. ستا نجوميان چرته دى، چې ستورو ته ګورى او مياشت په مياشت پېشګويانې کوى؟ هغوئ دې راشى او څۀ چې کېدونکى دى تا دې د هغې نه بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17502, 'Isaiah 47:14', 'Isaiah', 47, 14, '&nbsp;هغوئ په اور کښې د سوزېدونکى بوسو په شان دى چې خپل ځان د دې د لمبو نه نۀ شى بچ کولے. دا به د سکرو اور نۀ وى چې انسان ورته کښېنى او ځان ګرم کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17503, 'Isaiah 47:15', 'Isaiah', 47, 15, '&nbsp;هغوئ به تا مايوسه کړى، چا سره چې تۀ د ځوانۍ نه په وفادارۍ چلېدلے يې. هر يو به درنه په خپله مخه لاړ شى، او داسې به هيڅ څوک پاتې نۀ وى چې تاسو بچ کړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17504, 'Isaiah 48:1', 'Isaiah', 48, 1, '&nbsp;اے د يعقوب خاندانه، دا خبره واورئ، تاسو چې د بنى اِسرائيلو په نامه يادېږئ او د يهوداه اولاد يئ، او تاسو چې د مالِک خُدائ په نوم قسم خورئ او د بنى اِسرائيلو خُدائ پاک ته آواز کوئ، خو نۀ په کښې اخلاص شته او نۀ سمه طريقه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17505, 'Isaiah 48:2', 'Isaiah', 48, 2, '&nbsp;تاسو د مقدس ښار اوسېدونکى يئ او وايئ چې تاسو د بنى اِسرائيلو په خُدائ پاک باور کوئ، د چا نوم چې مالِک خُدائ ربُ الافواج دے. هغه فرمائى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17506, 'Isaiah 48:3', 'Isaiah', 48, 3, '&nbsp;”ما ډېر پخوا پېشګوئې کړې وه چې څۀ به کيږى، او بيا مې ناڅاپه هم دغه شان وکړل، او زما ټولې پېشګويانې رښتيا شوې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17507, 'Isaiah 48:4', 'Isaiah', 48, 4, '&nbsp;ما ته پته وه چې تاسو به څومره ضديان يئ، ستاسو د مرۍ رګونه به د اوسپنې په شان کلک او ستاسو تندى به لکه د مټکور غوز په شان وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17508, 'Isaiah 48:5', 'Isaiah', 48, 5, '&nbsp;نو ما ډېر پخوا ستاسو د راتلونکى وخت پېشګوئې وکړه، د حالاتو بيان مې د وړاندې نه وکړو، د دې دپاره چې تاسو دا دعوىٰ ونۀ کړئ چې ستاسو بُتانو او تراشلے شوو مجسمو د دې حُکم کړے وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17509, 'Isaiah 48:6', 'Isaiah', 48, 6, '&nbsp;ما چې د څۀ پېشګوئې کړې وه نو هغه هر څۀ شوى دى، خو تاسو د هغې منلو نه اِنکار وکړو. اوس به زۀ تاسو ته د نوؤ خبرو په حقله ووايم، دا هغه رازونه دى چې تاسو تر اوسه پورې نۀ دى اورېدلى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17510, 'Isaiah 48:7', 'Isaiah', 48, 7, '&nbsp;په تېره زمانه کښې داسې څۀ نۀ وُو شوى، بلکې هم اوس اوس دا ستا په عِلم کښې راغلل. داسې ځکه وشول چې تاسو ونۀ شئ وئيلے، چې مونږ ته مخکښې نه د دې پته وه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17511, 'Isaiah 48:8', 'Isaiah', 48, 8, '&nbsp;ما ته پته وه چې تاسو ناقابلِ اعتماد يئ، ځکه چې تاسو د وړوکوالى نه په باغيانو مشهور وئ. او هم دا وجه ده چې تاسو هيڅکله د دې په حقله نۀ دى اورېدلى، او دا ځکه د دې يوه خبره هم ستاسو غوږونو ته نۀ ده رارسېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17512, 'Isaiah 48:9', 'Isaiah', 48, 9, '&nbsp;زما د نوم د خاطره زۀ خپله غصه په قابو کښې ساتم، زما د ثناء صِفت د خاطره زۀ خپل ځان ستاسو د تباهۍ نه را ايساروم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17513, 'Isaiah 48:10', 'Isaiah', 48, 10, '&nbsp;ما تاسو صفا کړى يئ، خو داسې نه لکه چې سپين زر صفا کيږى، بلکې ما تاسو صفا کړى يئ، د مصيبت په بټۍ کښې مې آزمائيلى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17514, 'Isaiah 48:11', 'Isaiah', 48, 11, '&nbsp;زۀ چې څۀ کوم نو هغه زۀ د خپل خاطر په وجه کوم، زۀ نۀ غواړم چې زما د نوم بې‌عزتى وشى او نۀ به په خپل جلال کښې چا له برخه ورکړم، دا به زما وى او صرف زما به وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17515, 'Isaiah 48:12', 'Isaiah', 48, 12, '&nbsp;”اے بنى اِسرائيلو، زما غوره کړے شوو، ما ته غوږ ونيسئ. صرف زۀ خُدائ پاک يم، زۀ اولين او آخرين يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17516, 'Isaiah 48:13', 'Isaiah', 48, 13, '&nbsp;ما په خپل لاس باندې د زمکې بنيادونه لګولى دى او زما ښى لاس آسمانونه خوارۀ کړى دى. کله چې زۀ آواز ورکړم نو دوئ ټول يو ځائ حاضر شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17517, 'Isaiah 48:14', 'Isaiah', 48, 14, '&nbsp;ټولو خلقو، راغونډ شئ او واورئ. په معبودانو کښې کوم يو د دې پېشګوئې ورکړې ده؟ ما چې کوم سړے خوښ کړے دے هغه به په بابل حمله وکړى، او د بابليانو خلاف به خپل زور استعمالوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17518, 'Isaiah 48:15', 'Isaiah', 48, 15, '&nbsp;زۀ هغه څوک يم چې هغۀ ته مې آواز وکړو او راومې غوښتلو، د هغۀ مې لارښودنه وکړه او هغه به کاميابيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17519, 'Isaiah 48:16', 'Isaiah', 48, 16, '&nbsp;نو اوس ما له رانزدې شئ او چې زۀ څۀ وايم هغې ته غوږ ونيسئ. ما د شروع نه صفا خبره کړې ده، او ما همېشه خپله خبره رښتيا کړې ده.“ او زۀ اوس مالِک خُدائ تعالىٰ د خپل روح سره رالېږلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17520, 'Isaiah 48:17', 'Isaiah', 48, 17, '&nbsp;د بنى اِسرائيلو مقدس ذات، مالِک خُدائ ستاسو خلاصونکے فرمائى، ”زۀ مالِک خُدائ ستاسو خُدائ پاک يم، هغه ذات چې ستاسو د خپلې فائدې دپاره تاسو ته ښودنه کوى او هغه لار درته ښائى چې په کومه باندې درله تلل په کار دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17521, 'Isaiah 48:18', 'Isaiah', 48, 18, '&nbsp;خو کۀ صرف تاسو زما حُکمونو ته پام کړے وے. نو ستاسو امن به لکه د سيند په شان وو، او ستاسو صداقت به د سمندر د چپو په شان وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17522, 'Isaiah 48:19', 'Isaiah', 48, 19, '&nbsp;ستاسو اولاد به د شګو په شان ډېر او بې‌شمېره وے، او ما به هيڅ امکان نۀ وے پرېښے چې د هغوئ نام و نشان زما د وړاندې نه ختم شى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17523, 'Isaiah 48:20', 'Isaiah', 48, 20, '&nbsp;د بابل نه ووځئ. او د بابليانو نه وتښتئ. د خوشحالۍ سره د دې خبر چغه ووهئ، او د دُنيا تر ګُټ ګُټه پورې دا خبره مشهوره کړئ چې، ”مالِک خُدائ خپل خِدمت کوونکى بنى اِسرائيليان بچ کړى دى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17524, 'Isaiah 48:21', 'Isaiah', 48, 21, '&nbsp;کله چې مالِک خُدائ خپل خلق په خُشکه صحرا کښې روان کړل، هغوئ د تندې په وجه د تکليف سره مخ نۀ شول. د هغوئ دپاره يې د ګټ نه اوبۀ راوويستلې، هغۀ ګټ په مينځ بېل کړو او اوبۀ ترې نه راوبهېدلې.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17525, 'Isaiah 48:22', 'Isaiah', 48, 22, '&nbsp;مالِک خُدائ فرمائى، ”د شريرانو دپاره سلامتى نشته.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17526, 'Isaiah 49:1', 'Isaiah', 49, 1, '&nbsp;اے لرې قومونو، ما ته غوږ ونيسئ، اے هغه خلقو، چې لرې اوسېږئ. زما د پېدا کېدو نه مخکښې مالِک خُدائ زۀ خوښ کړم او زۀ يې خپل خِدمت کوونکے مقرر کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17527, 'Isaiah 49:2', 'Isaiah', 49, 2, '&nbsp;هغۀ زما خبرې د تُورې په شان تېرې کړې. او د خپل لاس د سورى لاندې يې پټ کړم، هغۀ زۀ د غشى په شان تېرۀ کړم او په خپل د غشو تيلۍ کښې يې پټ وساتلم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17528, 'Isaiah 49:3', 'Isaiah', 49, 3, '&nbsp;هغۀ ما ته وفرمائيل چې، ”تۀ زما خِدمت کوونکے بنى اِسرائيل يې، ستا په وجه به زما نوم ته جلال ملاويږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17529, 'Isaiah 49:4', 'Isaiah', 49, 4, '&nbsp;خو ما ووئيل چې، ”زما محنت بې‌فائدې دے، ما خپل طاقت بې‌فائدې او بې‌مقصده ضائع کړے دے، خو يقيناً چې زما حق مالِک خُدائ سره دے او زما خُدائ پاک به ما له اجر راکړى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17530, 'Isaiah 49:5', 'Isaiah', 49, 5, '&nbsp;خو زما د پېدا کېدو نه مخکښې، مالِک خُدائ زۀ مقرر کړم، هغۀ زۀ د دې دپاره خپل خِدمت کوونکے جوړ کړم چې د هغۀ خلق واپس راولم، او دا چې بنى اِسرائيليان د هغۀ د حضور وړاندې راغونډ کړم. مالِک خُدائ ما له عزت راکوى، او هغۀ ما له طاقت راکړے دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17531, 'Isaiah 49:6', 'Isaiah', 49, 6, '&nbsp;هغه فرمائى، ”زما خِدمت کوونکيه، زۀ ستا دپاره يو لوئ مقصد لرم. تۀ به نۀ صرف هغه بنى اِسرائيليان بحال کړې چې کوم ژوندى پاتې دى، بلکې زۀ به تا د قومونو دپاره رڼا وګرځوم نو چې دغه شان تۀ زما خلاصون ټولې دُنيا ته ورسوې.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17532, 'Isaiah 49:7', 'Isaiah', 49, 7, '&nbsp;د بنى اِسرائيل مقدس ذات او خلاصونکے هغه چا ته وائى چې د چا نه سخت نفرت شوے دے، د چا نه چې قومونو نفرت کړے دے چې دے د حکمرانانو خِدمت کوونکے دے، ”بادشاهان به تا وګورى او د عزت نه به درته پاڅيږى، شهزادګان به هم وګورى، او هغوئ به تا ته د عزت نه ټيټيږى. دا ځکه چې مالِک خُدائ خپل خِدمت کوونکے خوښ کړے دے، د بنى اِسرائيلو مقدس ذات خپلې وعدې پوره کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17533, 'Isaiah 49:8', 'Isaiah', 49, 8, '&nbsp;مالِک خُدائ فرمائى، ”کله چې ستاسو د بچ کېدو وخت راغلو، نو ما په تاسو نظر وکړو او د مدد دپاره مې ستاسو فرياد واورېدو. زۀ به ستاسو حِفاظت او ساتنه وکړم او ستاسو په ذريعه به د ټولو خلقو سره يو لوظ وکړم. او زۀ به يو ځل بيا تاسو په هغه مُلک کښې آباد کړم کوم مُلک چې اوس شاړ او ويجاړ پروت دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17534, 'Isaiah 49:9', 'Isaiah', 49, 9, '&nbsp;زۀ به قېديانو ته ووايم چې، تاسو آزاد يئ. او څوک چې په تيارۀ کښې وى نو هغوئ ته به ووايم چې، رڼا له راوځئ. هغوئ به د هغه ګډو په شان وى چې د غرونو په غونډو کښې څريږى،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17535, 'Isaiah 49:10', 'Isaiah', 49, 10, '&nbsp;هغوئ به هيڅکله نۀ اوږى شى او نۀ به کله تږى شى. د نمر او د صحرا ګرمى به هغوئ نۀ تنګوى، د هغوئ مشرى به هغه ذات کوى چې څوک د هغوئ سره مينه کوى. او هغه به يې د اوبو چينو له بوځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17536, 'Isaiah 49:11', 'Isaiah', 49, 11, '&nbsp;زۀ به په غرونو کښې يو لوئ سړک جوړ کړم او د خپلو خلقو دپاره به يوه لار جوړه کړم چې په هغې به مزل کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17537, 'Isaiah 49:12', 'Isaiah', 49, 12, '&nbsp;ګورئ زما خلق به د لرې لرې نه راځى، د شمال طرف او د نمرپرېواتۀ طرف نه، او د سينم نه به راځى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17538, 'Isaiah 49:13', 'Isaiah', 49, 13, '&nbsp;اے آسمانه، د خوشحالۍ چغې وهه. اے زمکې، خوشحالى وکړه. اے غرونو، د خوشحالۍ سندرې ووايئ. ځکه چې مالِک خُدائ خپلو خلقو له تسلى ورکړې ده، او هغه به په خپلو کړېدلو خلقو رحم وکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17539, 'Isaiah 49:14', 'Isaiah', 49, 14, '&nbsp;خو د يروشلم خلقو ووئيل، ”مالِک خُدائ مونږ پرېښى يُو. او هغۀ مونږ هېر کړى يُو.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17540, 'Isaiah 49:15', 'Isaiah', 49, 15, '&nbsp;”هيڅکله نه. يو مور خپل د پيو ماشوم هېرولے شى څۀ؟ او چې کوم بچے ترې نه پېدا شوے وى نو د هغۀ سره به مينه نۀ کوى څۀ؟ کۀ يوه مور خپل بچے هېر هم کړى، خو زۀ به تاسو هيڅکله هم هېر نۀ کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17541, 'Isaiah 49:16', 'Isaiah', 49, 16, '&nbsp;ګوره ما ستا نوم د خپلو لاسونو په تلو باندې ليکلے دے، او ستا دېوالونه همېشه زما په وړاندې دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17542, 'Isaiah 49:17', 'Isaiah', 49, 17, '&nbsp;څوک چې تا بيا آبادول غواړى نو هغه زر واپس راروان دے، او چا چې تۀ تباه کړے يې نو هغوئ درنه ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17543, 'Isaiah 49:18', 'Isaiah', 49, 18, '&nbsp;ګېرچاپېره نظر وګرځوه او وګوره. ستا خلق راغونډيږى او هغوئ کورونو ته راروان دى. مالِک خُدائ فرمائى چې زما دې په خپل ذات قسم وى، هغوئ به تا ته داسې راغونډ شى لکه څنګه چې په ناوې کالى امبار وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17544, 'Isaiah 49:19', 'Isaiah', 49, 19, '&nbsp;ستا مُلک تباه شوے وو او وران ويجاړ وو، خو اوس چې څوک د اوسېدو دپاره ورله راروان دى، نو دا مُلک به د هغوئ د اوسېدو دپاره ډېر وړوکے وى. او چا چې تاسو په کنډرو کښې پرېښودئ نو هغوئ به ستاسو نه لرې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17545, 'Isaiah 49:20', 'Isaiah', 49, 20, '&nbsp;ستاسو کوم خلق چې په جلاوطنۍ کښې پېدا شوى وُو نو هغه خلق به يوه ورځ تا ته ووائى، دا مُلک خو وړوکے دے، مونږ ته نوره زمکه په کار ده.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17546, 'Isaiah 49:21', 'Isaiah', 49, 21, '&nbsp;بيا به تۀ په خپل زړۀ کښې ووائې، دا دومره بچى ما له چا راکړل؟ زما بچى خو ختم شوى وُو او نور بچى مې نۀ کېدل. زۀ جلاوطن کړے شوے وم او شړلے شوے وم، دا بچى ما له چا راکړل؟ زۀ خو يواځې پاتې وم، دا بچى د کوم ځائ نه راغلل؟“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17547, 'Isaiah 49:22', 'Isaiah', 49, 22, '&nbsp;خُدائ تعالىٰ داسې فرمائى، ”ګورئ، زۀ به قومونو ته اِشاره وکړم، او هغوئ به ستاسو زامن په غېږ کښې او ستاسو لوڼه په اوږو کورونو ته راولى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17548, 'Isaiah 49:23', 'Isaiah', 49, 23, '&nbsp;بادشاهان به ستاسو دپاره د پلارانو په شان وى او ستاسو خيال به ساتى، او د هغوئ مَلِکې به ستاسو او ستاسو د بچو دپاره د ميندو په شان وى. هغوئ به ستاسو په وړاندې ټيټ شى او ستاسو په پښو دوړې به څټى، نو بيا به تاسو ته پته ولګى چې زۀ مالِک خُدائ يم، هر څوک هم چې زما د مدد په طمع وى نو هغه به نۀ شرميږى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17549, 'Isaiah 49:24', 'Isaiah', 49, 24, '&nbsp;څوک د جنګيالى نه مالِ غنيمت اخستلے شى څۀ؟ يا څوک د يو ظالم کس نه قېديان خلاصولے شى څۀ؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17550, 'Isaiah 49:25', 'Isaiah', 49, 25, '&nbsp;خو مالِک خُدائ وفرمائيل، ”يقيناً چې د جنګيالى نه به قېديان بوتلے شى، او د ظالم کس مالِ غنيمت به ونيولے شى. هر څوک هم چې تا سره جنګ کوى نو زۀ به هغوئ سره جنګ کوم، او هم زۀ به ستا د بچو حِفاظت کوم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17551, 'Isaiah 49:26', 'Isaiah', 49, 26, '&nbsp;چا چې په تا ظلم کړے دے زۀ به په هغوئ باندې د هغوئ خپله غوښه وخوروم، هغوئ به د خپلې وينې په څښلو سره د ميو په شان په نشه کښې وى. نو داسې به بيا ټولو انسانانو ته پته ولګى چې زۀ مالِک خُدائ يم، زۀ هغه ذات يم څوک چې تاسو بچ کوى او تاسو آزادوى او د بنى اِسرائيلو طاقتور ذات يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17552, 'Isaiah 50:1', 'Isaiah', 50, 1, '&nbsp;مالِک خُدائ فرمائى، ”د يهوداه خلقو راشئ، او ما ته هغه طلاق نامه وښايئ چې ما ستاسو مور له ورکړې وه او ستاسو مور مې پرېښوده. هغه طلاق نامه چرته ده؟ او يا ما ته هغه قرض ورکوونکے وښايئ چې ما د خپل قرض په وجه تاسو ورته حواله کړى وئ هغه چرته دے؟ ګورئ هم ستاسو د خپلو ګناهونو له وجې خرڅ کړے شوئ او ستا د خپلو ګناهونو په وجې ستاسو مور وشړلې شوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17553, 'Isaiah 50:2', 'Isaiah', 50, 2, '&nbsp;چې زۀ راغلم نو څوک هم نۀ وو، ولې؟ چې ما آواز وکړو نو چا هم جواب رانۀ کړو، ولې؟ ولې زما لاس دومره کمزورے وو څۀ چې تاسو مې خلاصولے نۀ شوئ؟ ولې زۀ دومره کمزورے يم څۀ چې تاسو بچ کولے نۀ شم؟ زما يو حُکم سره سمندر اوچ شى او سيندونه په صحرا بدل شى، او بغېر اوبو نه کبان مړۀ شى او هر طرف ته بدبوئ خوره شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17554, 'Isaiah 50:3', 'Isaiah', 50, 3, '&nbsp;هم زۀ آسمان باندې توره کپړه اچوم او هم زۀ هغې ته د غم جامې اچوم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17555, 'Isaiah 50:4', 'Isaiah', 50, 4, '&nbsp;خُدائ تعالىٰ ما له د يو اُستاذ ژبه راکړې ده، د دې دپاره چې ستړو خلقو له تسلى ورکړم. هر سحر هغه ما پاڅوى او هغه زما په زړۀ کښې دا جذبه اچوى چې د هغۀ ښودنې ته غوږ ونيسم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17556, 'Isaiah 50:5', 'Isaiah', 50, 5, '&nbsp;خُدائ تعالىٰ ما ته صفا وينا کړې ده، او ما د هغۀ نه سرکشى نۀ ده کړې او نۀ د هغۀ نه اوړېدلے يم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17557, 'Isaiah 50:6', 'Isaiah', 50, 6, '&nbsp;چا چې زما وهل غوښتل ما هغوئ ته خپله ملا وړاندې کړه، چا چې زما نه ږيره ويستله ما هغوئ ته خپل مخ وړاندې کړو. ما د هغوئ د بې‌عزتۍ او توکاڼو نه خپل مخ نۀ دے پټ کړے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17558, 'Isaiah 50:7', 'Isaiah', 50, 7, '&nbsp;خو خُدائ تعالىٰ زما مدد کوى نو زما بې‌عزتى به نۀ کيږى. ما د هغۀ د مرضۍ پوره کولو کلکه اراده کړې ده. ما ته پته ده چې زۀ به د شرم سره نۀ مخ کېږم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17559, 'Isaiah 50:8', 'Isaiah', 50, 8, '&nbsp;څوک چې ما ته صداقت ښائى هغه نزدې دے، څوک دا جرأت کولے شى چې په ما اِلزامونه ولګوى؟ زما مخالف چرته دے چې په ما اِلزام ولګوى. هغه دې رامخامخ شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17560, 'Isaiah 50:9', 'Isaiah', 50, 9, '&nbsp;هم خُدائ تعالىٰ زما ملګرتيا کوى، نو څوک به ما مجرم ثابت کړى؟ په ما باندې ټول اِلزام لګوونکى به ورک شى هغوئ به داسې ختم شى لکه چې کپړه چينجو خوړلې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17561, 'Isaiah 50:10', 'Isaiah', 50, 10, '&nbsp;په تاسو کښې څوک د مالِک خُدائ نه يريږى او د هغۀ د خِدمت کوونکى آواز منى؟ څوک چې په تيارۀ کښې روان وى هيڅ رڼا ورسره نۀ وى خو بيا هم دې د هغۀ ايمان په مالِک خُدائ وى او د هغۀ توکل دې په خُدائ پاک باندې وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17562, 'Isaiah 50:11', 'Isaiah', 50, 11, '&nbsp;خو تاسو خلق څوک چې خپل ځانونه بَلو غشو سره وسله بند کړئ، نو هم د خپل اور د شغلو په رڼا کښې لاړ شئ. زما د لاس نه به تاسو ته هم دا اجر ملاويږى، تاسو به سخت درد کښې راپرېوځئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17563, 'Isaiah 51:1', 'Isaiah', 51, 1, '&nbsp;”ما ته غوږ ونيسئ، څوک چې صداقت غواړئ، او د مالِک خُدائ لټون کوئ. د هغه ګټ په حقله سوچ وکړئ د کوم نه چې تراشلے شوى يئ، د هغه کان په حقله سوچ وکړئ چې د کوم نه تاسو راويستلے شوى يئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17564, 'Isaiah 51:2', 'Isaiah', 51, 2, '&nbsp;د خپل پلار نيکۀ اِبراهيم او مور ساره په حقله سوچ وکړئ، چې تاسو يې زيږولى يئ. کله چې ما اِبراهيم راوغوښتلو، نو هغه بې‌اولاده وو، خو ما هغۀ له برکت ورکړو او ډېر اولاد مې ورکړو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17565, 'Isaiah 51:3', 'Isaiah', 51, 3, '&nbsp;يقيناً چې مالِک خُدائ به بيا صيون له تسلى ورکړى. او د هغې په ټولو کنډرو به ترس وکړى. د هغې صحرا به د باغِ عدن په شان ګلستان کړى، د هغې بنجره زمکه به د مالِک خُدائ د باغ په شان شى. هلته به خندا او خوشحالى وى، او د ثناء صِفت او د شکرانې حمدونه به وئيلے شى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17566, 'Isaiah 51:4', 'Isaiah', 51, 4, '&nbsp;زما خلقو بنى اِسرائيلو، ما ته غوږ ونيسئ، زۀ چې څۀ وايم هغې ته توجو وکړئ، زۀ به قومونو ته خپل تعليمات وښايم، زما اِنصاف به د هغوئ دپاره رڼا وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17567, 'Isaiah 51:5', 'Isaiah', 51, 5, '&nbsp;زما رحم او اِنصاف زر راروان دى. زما خلاصون په لاره دے. زما مضبوط لاس به قومونو له اِنصاف راوړى. لرې مُلکونه زما انتظار کوى، هغوئ په دې طمع دى چې بچ يې کړم.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17568, 'Isaiah 51:6', 'Isaiah', 51, 6, '&nbsp;بره آسمان ته وګورئ، او لاندې زمکې ته وګورئ. آسمانونه به د لوګى په شان ورک شى، او زمکه به د زړې چِرړې په شان ورَسته شى، او د دې ټول خلق به د مچانو په شان مړۀ شى. خو زما خلاصون به د همېشه دپاره وى، او زما صداقت به هيڅکله نۀ ختميږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17569, 'Isaiah 51:7', 'Isaiah', 51, 7, '&nbsp;اے هغه خلقو چې څوک په صداقت پوهېږئ، ما ته غوږ ونيسئ، اے هغه خلقو چې د چا په زړُونو کښې چې زما تعليم اچولے شوے دے. کله چې خلق په تاسو پورې خندا کوى يا ستاسو بې‌عزتى کوى، نو مۀ يرېږئ،', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17570, 'Isaiah 51:8', 'Isaiah', 51, 8, '&nbsp;ولې چې چينجى به هغوئ لکه د کپړې په شان وخورى، او چينجى به يې لکه د وړۍ په شان وخورى. خو زما صداقت به تر همېشه پورې وى، او زما خلاصون به تر ټولو نسلونو پورې قائم وى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17571, 'Isaiah 51:9', 'Isaiah', 51, 9, '&nbsp;اے مالِکه خُدايه، پاڅه. ويښ شه او زمونږ مدد وکړه. د خپل طاقت نه کار واخله او مونږ بچ کړه، خپل طاقت داسې استعمال کړه لکه څنګه دې چې مخکښې استعمالولو. دا تۀ وې چې سمندرى بلا راحب دې ټوټې ټوټې کړه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17572, 'Isaiah 51:10', 'Isaiah', 51, 10, '&nbsp;دا هم تۀ وې چې سمندر دې اوچ کړو او په اوبو کښې دې لار جوړه کړه، نو چې هغه څوک په دې ژور سمندر کښې تېر شى چې کوم دې بچ کول.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17573, 'Isaiah 51:11', 'Isaiah', 51, 11, '&nbsp;د چا فديه چې مالِک خُدائ ورکړې ده نو هغوئ به راواپس شى، او څنګه چې صيون ته ننوځې نو د خوشحالۍ نه به چغې وهى او سندرې به وائى. هغوئ به د همېشه دپاره خوشحاله وى، او د غم او پرېشانۍ نه به په امن وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17574, 'Isaiah 51:12', 'Isaiah', 51, 12, '&nbsp;”زۀ، صرف زۀ تاسو له تسلى درکوم. نو بيا تاسو د انسانانو نه ولې يرېږئ، چې هغوئ د واښو نه هم زر فنا کيږى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17575, 'Isaiah 51:13', 'Isaiah', 51, 13, '&nbsp;تاسو هغه مالِک خُدائ هېر کړے دے چا چې پېدا کړئ، چا چې آسمانونه خوارۀ کړل او چې د زمکې بنيادونه يې ولګول؟ تاسو هر وخت د هغه خلقو نه ولې په يره کښې يئ څوک چې د غصې نه په تاسو باندې ظلم زياتے کوى، څوک چې ستاسو د تباه کولو دپاره تيار دى؟ اوس د هغوئ غصه چرته ده؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17576, 'Isaiah 51:14', 'Isaiah', 51, 14, '&nbsp;قېديان به زر راخلاص شى، هغوئ به په قېدخانه کښې نۀ مرى او د هغوئ سره به د خوراک کمے نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17577, 'Isaiah 51:15', 'Isaiah', 51, 15, '&nbsp;زۀ مالِک خُدائ ستاسو خُدائ پاک يم، سمندر ما راپاڅولو او د دې چپې مې غضبناکې کړې. زما نوم مالِک خُدائ ربُ الافواج دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17578, 'Isaiah 51:16', 'Isaiah', 51, 16, '&nbsp;ما خپل کلام ستاسو په ژبه ګويا کړو، او د خپل لاس د سورى لاندې مې تاسو پټ کړئ، آسمانونه مې خوارۀ کړل او د زمکې بنيادونه مې کېښودل، او ما يروشلم ته وفرمائيل، تاسو زما خلق يئ.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17579, 'Isaiah 51:17', 'Isaiah', 51, 17, '&nbsp;ويښ شه. ويښ شه. پاڅه ودرېږه اے يروشلمه. تا د مالِک خُدائ د لاس نه هغه جام څښلے دے کوم چې د هغۀ د غصې نه ډک وو، دا جام تا تر آخرى قطرې پورې وڅښلو کوم چې د نشه ورو شرابو نه ډک وو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17580, 'Isaiah 51:18', 'Isaiah', 51, 18, '&nbsp;ستا چې څومره زامن شوى دى په هغوئ کښې يو هم نشته چې ستا رهنمائى وکړى، تا چې څومره زامن لوئ کړى دى په هغوئ کښې يو هم نشته چې تا د لاس نه ونيسى او بو دې ځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17581, 'Isaiah 51:19', 'Isaiah', 51, 19, '&nbsp;په تا باندې دوه افتونه راغلې دى يعنې تباهى او بربادى، جنګ او قحط. خو څوک پاتې دى چې تا سره همدردى وکړى؟ او څوک پاتې دې چې تا له تسلى درکړى؟', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17582, 'Isaiah 51:20', 'Isaiah', 51, 20, '&nbsp;ستا خلق د کمزورۍ د وجې نه په هره کوڅه کښې غورزيږى، هغوئ بې‌مددګاره لکه د هوسۍ په شان په جال کښې انښتى دى. او د مالِک خُدائ غضب په هغوئ نازل دے او خُدائ پاک هغوئ رټلى دى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17583, 'Isaiah 51:21', 'Isaiah', 51, 21, '&nbsp;اے تاسو چې په مصيبت کښې ګېر يئ واورئ، څوک چې په نشه کښې يئ خو د ميو له وجې نه نه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17584, 'Isaiah 51:22', 'Isaiah', 51, 22, '&nbsp;مالِک خُدائ ستاسو خُدائ پاک چې د خپل قوم دپاره جنګيږى داسې فرمائى، ”ګورئ، ما دا د نشه ورو شرابو نه ډک جام ستاسو د لاس نه لرې کړے دے، نو تاسو به نور زما د غصې د جام نه نۀ څښئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17585, 'Isaiah 51:23', 'Isaiah', 51, 23, '&nbsp;دا به زۀ هغه خلقو له ورکړم چا چې په تاسو باندې ظلم زياتے کولو، هغه خلقو له چا چې تاسو په کوڅو کښې څملولئ او پښې به يې درباندې کېښودې او په تاسو به ګرځېدل.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17586, 'Isaiah 52:1', 'Isaiah', 52, 1, '&nbsp;اے يروشلمه، پاڅه، ويښ شه. خپلې د طاقت جامې واغونده. اے مقدسې ښاريې، د شان او شوکت والا جامې واغونده. ناسنته او ناپاک خلق به هيڅکله ستا په دروازو بيا درننه نۀ وځى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17587, 'Isaiah 52:2', 'Isaiah', 52, 2, '&nbsp;اے يروشلمه، د ځان نه خاورې وڅنډه او پاڅه او په تخت کښېنه. اے د صيون قېد شوې لورې، د غلامۍ زنځيرونه د خپلې غاړې نه وشلوه.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17588, 'Isaiah 52:3', 'Isaiah', 52, 3, '&nbsp;مالِک خُدائ فرمائى، ”کله چې تاسو غلامان شوئ، نو ستاسو په سر پېسې نۀ وې ورکړے شوې، او چې کله تاسو آزادولے شئ نو ستاسو په سر به پېسې نۀ شى ورکولے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17589, 'Isaiah 52:4', 'Isaiah', 52, 4, '&nbsp;مالِک خُدائ تعالىٰ فرمائى، ”ډېره موده وړاندې زما خلق مِصر ته د څۀ مودې دپاره لاړل، خو اوس اسوريان بغېر د څۀ وجې په هغوئ باندې ظلم زياتے کوى.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17590, 'Isaiah 52:5', 'Isaiah', 52, 5, '&nbsp;مالِک خُدائ فرمائى، ”او په بابل کښې هم هغه کار شوے دے يعنې، زما خلق قېديان دى او د هغوئ په سر هيڅ پېسې نۀ دى ورکړے شوې. څوک چې په هغوئ حکومت کوى نو هغوئ هر وخت زما د نوم سپکاوے کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17591, 'Isaiah 52:6', 'Isaiah', 52, 6, '&nbsp;نو داسې به زما خلقو ته زما د نوم پته وى، او داسې به هم په هغه ورځ هغوئ ته پته ولګى چې هم زۀ کلام کوم او زۀ حاضر يم.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17592, 'Isaiah 52:7', 'Isaiah', 52, 7, '&nbsp;د هغوئ قدمونه څومره ښکلې دى چې په غرونو باندې روان دى او زېرے راوړى. ځکه چې هغه به د امن و امان پېغام او د خلاصون اعلان کوى، او صيون ته به وائى، ”ستا خُدائ پاک بادشاه دے.“', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17593, 'Isaiah 52:8', 'Isaiah', 52, 8, '&nbsp;څوک چې د ښار حفاظت کوى نو هغوئ د خوشحالۍ چغې وهى، هغوئ په خپلو سترګو باندې ګورى چې مالِک خُدائ صيون ته واپس راروان دے.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17594, 'Isaiah 52:9', 'Isaiah', 52, 9, '&nbsp;اے د يروشلم کنډرو، په يو ځائ د خوشحالۍ سندرې ووايئ. مالِک خُدائ به خپل ښار بچ کړى او خپلو خلقو له به تسلى ورکړى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17595, 'Isaiah 52:10', 'Isaiah', 52, 10, '&nbsp;مالِک خُدائ به د خپل مقدس طاقت نه کار واخلى، خُدائ پاک به خپل خلق بچ کړى، او ټول قومونه او ټوله دُنيا به په خپلو سترګو دا وګورى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17596, 'Isaiah 52:11', 'Isaiah', 52, 11, '&nbsp;ځئ، ځئ، د دغه ځائ نه ځئ. چې يو ناپاک څيز له هم لاس ورنۀ وړئ، څوک چې د مالِک خُدائ د کور سامان وړى تاسو خپل ځانونه پاک وساتئ او لاړ شئ.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17597, 'Isaiah 52:12', 'Isaiah', 52, 12, '&nbsp;ضرورى نۀ ده چې تاسو په منډه لاړ شئ، او نۀ تاسو ته اچانک د تېښتې ضرورت شته، ولې چې مالِک خُدائ به ستاسو نه وړاندې ځى، د بنى اِسرائيلو خُدائ پاک به د وروستو نه ستاسو حِفاظت کوى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17598, 'Isaiah 52:13', 'Isaiah', 52, 13, '&nbsp;ګورئ، زما خِدمت کوونکے به په خپل کار کښې کامياب شى، د هغۀ به ډېر زيات عزت کيږى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17599, 'Isaiah 52:14', 'Isaiah', 52, 14, '&nbsp;خو کله چې يې هغه وليدو نو ډېر خلق حېران شول، د هغۀ شکل صورت داسې خراب وو چې هغه د نورو انسانانو په شان نۀ ښکارېدو.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]'),
(17600, 'Isaiah 52:15', 'Isaiah', 52, 15, '&nbsp;اوس به ډېر قومونه هغۀ ته حېران شى، او د هغۀ په وړاندې به د بادشاهانو د خولې نه خبرې نۀ وځى. ځکه چې هغوئ به هغه څۀ وګورى چې د څۀ ورته وئيلے شوى نۀ وى، او هغوئ به په هغه څۀ پوهه شى د څۀ چې يې اورېدلى نۀ وى.', '', 'OT', 'yousafzai2019', 'yousafzai', '', '', 1761754199, 1761754199, '[]');